   "id": "za4d547f0",
   "sez": "viaggi",
   "titolo": "Turismo e intelligenza artificiale: i dubbi dei manager allo Skift Global Forum",
   "orig": "Skift Global Forum 2026: 7 Insights From Travel Industry Leaders",
   "lead": "Il settore dei viaggi sta adottando rapidamente l'intelligenza artificiale, ma deve ancora risolvere questioni di fondo come la fiducia, il coordinamento tra operatori e i ritorni economici. È quanto emerge da un sondaggio tra i dirigenti delle aziende turistiche presenti allo Skift Global Forum 2026, che ha individuato sette indicazioni su dove il settore vede opportunità e quali siano le sue principali preoccupazioni. Le fonti non riportano i dati numerici del sondaggio. Lo riferisce Skift.",
   "more": [
    "Skift è una testata specializzata nell'industria dei viaggi che organizza ogni anno un forum con i dirigenti del settore. Nel turismo l'intelligenza artificiale viene usata per assistenti virtuali, prenotazioni e prezzi personalizzati, ma resta aperta la questione della fiducia dei viaggiatori verso consigli e scelte automatizzate."
   ],
