   "id": "z12343ed4",
   "sez": "organizzazioni",
   "titolo": "Aiea: il Kenya gestisce in sicurezza i rifiuti radioattivi",
   "orig": "IAEA Mission Finds Kenya Committed to Safe Management of Radioactive Waste as it Develops a Nuclear Power Programme",
   "lead": "Una missione dell'Agenzia internazionale per l'energia atomica ha verificato che il Kenya è impegnato a gestire in modo sicuro i propri rifiuti radioattivi. La valutazione arriva mentre il Paese africano sta sviluppando un programma per produrre energia nucleare. L'Aiea, con sede a Vienna, invia questo tipo di missioni su richiesta degli Stati per controllare che le loro pratiche rispettino gli standard internazionali di sicurezza. Le fonti non riportano i dettagli delle raccomandazioni. Lo riferisce l'Agenzia internazionale per l'energia atomica.",
   "more": [
    "L'Agenzia internazionale per l'energia atomica è un'organizzazione collegata alle Nazioni Unite, nata nel 1957, che promuove l'uso pacifico dell'energia nucleare e ne controlla la sicurezza. I rifiuti radioattivi provengono non solo dalle centrali, ma anche da ospedali, industria e ricerca, e richiedono per lungo tempo un isolamento sicuro."
   ],
