   "id": "z017eb749",
   "sez": "cultura",
   "titolo": "«Nobody Wants This», la nuova stagione punta su un'altra coppia",
   "orig": "Nobody Wants This review – prepare to fall in love again … with a different couple",
   "lead": "The Guardian recensisce la nuova stagione di «Nobody Wants This», la commedia romantica di successo con Adam Brody e Kristen Bell. I protagonisti Noah e Joanne vanno a vivere insieme e la serie resta piacevole, ma secondo il quotidiano la magia dell'innamoramento iniziale non può ripetersi. Chi cerca l'emozione di una nuova storia d'amore, osserva la recensione, la troverà piuttosto nei fratelli dei due protagonisti, la cui relazione potrebbe conquistare il pubblico. Lo riferisce The Guardian.",
   "more": [
    "«Nobody Wants This» è una serie di Netflix uscita nel 2024. Racconta la storia d'amore tra un rabbino, interpretato da Adam Brody, e una conduttrice di podcast non ebrea, interpretata da Kristen Bell. La serie ha avuto un grande successo di pubblico ed è stata rinnovata per altre stagioni."
   ],
