   "titolo": "Liberia, l'economista Samuel Jackson chiede di potersi curare all'estero",
   "orig": "Liberia: Samuel Jackson Begs Court for Medical Leave Amid Health Concerns",
   "lead": "In Liberia l'economista Samuel Jackson ha chiesto al giudice Onesimus Barwon, del Tribunale penale «A» di Monrovia, di concedergli un permesso per motivi di salute. Jackson vuole recarsi all'estero per ricevere cure mediche specialistiche, citando preoccupazioni per le sue condizioni. Le fonti non precisano di quale procedimento sia imputato né quali siano i suoi problemi di salute, e non riportano ancora la decisione del giudice. Lo riferisce FrontPage Africa.",
