   "titolo": "Firefly Wedding, Kazuyuki Okitsu nel cast dell'anime. Il doppiaggio inglese debutta il 23 ottobre",
   "orig": "Firefly Wedding TV Anime Casts Kazuyuki Okitsu",
   "lead": "La serie animata tratta da Firefly Wedding aggiunge un nome al cast. Il doppiatore Kazuyuki Okitsu darà la voce a Eishin Nitobe, uno dei personaggi della storia. Lo ha annunciato Anime News Network. Nello stesso tempo Crunchyroll ha presentato la versione doppiata in inglese della serie e ne ha reso noti la data di uscita, il cast e la squadra tecnica. Il primo episodio in inglese sarà disponibile dal 23 ottobre. L'annuncio arriva quindi alla vigilia del debutto internazionale della serie.",
   "more": [
    "Crunchyroll è una delle principali piattaforme di streaming dedicate all'animazione giapponese. Molte serie vengono distribuite all'estero con i sottotitoli in contemporanea con il Giappone, mentre il doppiaggio in inglese arriva in un secondo momento. Nell'industria degli anime i doppiatori, chiamati seiyū, hanno grande notorietà e spesso il loro nome contribuisce a richiamare il pubblico."
   ],
