 "contesti": {
  "zda3ea83a": "Lo scorso dicembre Trump ha citato in giudizio la BBC per diffamazione, contestando il montaggio di Panorama che accostava due sezioni diverse del suo discorso del 2021, ritenuto fuorviante. Nel corso della causa i legali dell'emittente hanno denunciato i rinvii del presidente nel fissare la propria deposizione, fino all'intervento del giudice federale.",
  "z3c84f3c2": "Inghilterra e Sri Lanka sono impegnate in Pakistan in una serie triangolare di One-Day International. Nell'incontro di Rawalpindi l'Inghilterra, trascinata dal record di Brook, ha fissato un punteggio di 430, apparentemente fuori portata. Lo Sri Lanka ha invece completato una rimonta tra le più ampie mai registrate nel formato.",
  "z1dd7a947": "Negli ultimi mesi Carney ha moltiplicato le missioni all'estero per allargare i mercati del Canada, in risposta all'orientamento protezionistico degli Stati Uniti guidati da Trump. La tappa di Ankara è l'ultima di questa serie e porta le relazioni bilaterali al livello di partenariato strategico.",
  "z3fd5edaf": "Negli ultimi anni gli scienziati hanno documentato ripetuti episodi di sbiancamento di massa dei coralli legati al riscaldamento degli oceani. L'IUCN ha ora condotto la prima valutazione complessiva dello stato di rischio degli ecosistemi corallini su scala mondiale, i cui risultati sono stati diffusi giovedì.",
  "z8ab6c070": "Nel nord dell'Etiopia le ostilità in corso continuano ad aggravare la situazione umanitaria e sanitaria. Nell'area di Abyei, il governo del Sud Sudan ha condannato il 21 ottobre un attacco mortale con droni attribuito alle forze armate sudanesi contro il mercato di Amiet, chiedendo un'indagine.",
  "z91bc41fd": "Nel corso dell'anno la Germania ha registrato diversi casi di presunto spionaggio per conto della Russia e le forze armate hanno alzato il livello di minaccia di sabotaggio. Parallelamente, l'FSB russo ha arrestato un cittadino tedesco accusandolo di aver combattuto come mercenario per l'Ucraina.",
  "zd13eb84d": "Il rialzo del gasolio ha innescato la mobilitazione degli autotrasportatori, con blocchi stradali e presidi, mentre i pescherecci sono rimasti fermi nei porti per protestare anche contro le politiche europee sulla pesca. Il governo ha valutato la precettazione; dopo il decreto le sigle principali hanno sospeso la mobilitazione, ma proseguono alcuni sit-in.",
  "z5aa28c26": "Negli ultimi tempi si sono moltiplicate le proteste dei viaggiatori contro gli host che, pur incassando una tariffa per le pulizie, chiedevano agli ospiti di rassettare l'alloggio al termine del soggiorno. Airbnb ha quindi annunciato nuove linee guida sulle regole della casa, applicabili dal 20 novembre.",
  "zba92ddc9": "Le indagini della polizia hanno portato all'individuazione di un alloggio in cui erano ammassati 74 migranti. Gli investigatori ritengono che il gruppo fosse in attesa di essere trasferito nella Spagna peninsulare da un'organizzazione dedita al traffico di persone, di cui l'arrestato sarebbe parte.",
  "z9739b145": "Il terremoto è avvenuto nella tarda serata di oggi in un'area remota e ad alta quota del nord del Tibet. Le prime notizie parlano di vittime, ma non è stato ancora diffuso un bilancio. La regione è tra le più sismiche dell'Asia: all'inizio del 2025 un altro forte sisma in Tibet aveva provocato più di cento morti.",
  "z01424c81": "Negli ultimi mesi l'amministrazione Trump ha colpito la Corte penale internazionale con sanzioni sempre più ampie e il presidente americano ha promesso di smantellarla «mattone dopo mattone». In risposta, i Paesi europei hanno dichiarato il loro sostegno all'indipendenza del tribunale. Il premio Sacharov arriva in questo clima di scontro tra Washington e la Corte.",
  "z1df9a06f": "Stephen Hubbard era stato catturato a Izium durante l'occupazione russa e imprigionato con l'accusa di essere un mercenario al servizio dell'Ucraina. Per anni la sua famiglia ha avuto pochissime possibilità di intervenire, come racconta il figlio. Nelle ultime settimane Trump aveva chiesto a Putin di liberarlo, mentre proseguivano i contatti diplomatici tra Washington e Mosca.",
  "z2f7c97f9": "Nei giorni scorsi Champi si è rafforzato fino a diventare un super tifone, tra i più intensi della stagione nel Pacifico, prima di iniziare a perdere forza avvicinandosi a Taiwan. Le autorità hanno preparato l'isola all'impatto, mentre i voli venivano cancellati e le esercitazioni militari nella regione venivano modificate.",
  "zb60d1577": "Le manifestazioni sono cominciate il 17 ottobre. Lo scorso fine settimana, a margine delle proteste, ci sono state violenze e saccheggi. A Parigi le autorità hanno introdotto un coprifuoco notturno nelle zone di République e delle Halles. Molte città hanno poi vietato i raduni previsti per sabato."
 },
